/** The Annex 4 form, as returned by `GET /forms/{id}`. */
export function annex4(overrides: Partial<FormDetail> = {}): FormDetail {
  return {
    id: 1,
    tender_id: 1,
    title: "Annex 4 — Conditions of participation and self-declaration",
    file_name: "Annex_4_Conditions of Participation and Company Self-Declaration.docx",
    file_format: "docx",
    field_counts: { fields: 49, yes_no: 17, signatures: 1 },
    estimated_fill_seconds: 200,
    pages: [
      { width: 595.35, height: 842.0 },
      { width: 595.35, height: 842.0 },
      { width: 595.35, height: 842.0 },
    ],
    fields: annex4Fields,
    ...overrides,
  };
}

/** An Annex 4 field by its key. */
export function annex4Field(key: string): FormField {
  const field = annex4Fields.find((candidate) => candidate.key === key);
  if (!field) throw new Error(`No Annex 4 field ${key}`);
  return field;
}
